export const photosByCategory = (c: PhotoCategory | "All") =>
  c === "All" ? PHOTOS : PHOTOS.filter((p) => p.category === c);

export const photo = (slug: string) => PHOTOS.find((p) => p.slug === slug) ?? PHOTOS[0];

/** Stable pick used for editorial slots so layouts stay deterministic. */
export const pickPhotos = (...slugs: string[]) => slugs.map(photo);
